action.mutation:
mutation CreateOrder($payload: [OrderCreatePayloadInput!]!) {
  mutation: createOrder(payload: $payload) {
    id
    number
  }
}

mutation UpdateOrder($payload: [OrderUpdatePayloadInput!]!) {
  mutation: updateOrder(payload: $payload) {
    id
    number
  }
}

